sys.path.insert(0,str(Path(__file__).resolve().parent));import kb
from extract_workbooks import fm,write,relative
ROOT=Path(__file__).resolve().parents[1];JOB='job-000001';S={s['source_id']:s for s in kb.sources(ROOT)};PART=Path('shared/reference/participants');SETS=Path('shared/reference/message-sets');MESS=Path('shared/reference/messages')
def put(p,b):write(ROOT,ROOT/p,b,JOB)
def l(p,t,title):return '['+title+']('+relative(ROOT/p,ROOT/t)+')'
def c(p,sid,loc):return kb.source_link(ROOT,ROOT/p,S[sid])+', '+loc+'.'
def f(kind,**kw):return fm(domain='shared',document_kind=kind,**kw)
BFH=Path(S['src-000349']['set_path']);BAH=Path(S['src-000011']['set_path']);BDOC=BAH/'documents/src-000011';FDOC=BFH/'documents/src-000349'
roles={
'bfh-file-sender':('File sender',['sender of the file','sender'],'The participant that creates and delivers the file in the BFH exchange. It is scoped to file delivery, and is not automatically the BAH creator of every contained message.','Assigns the unique PayloadIdentifier and CreationDateAndTime. Supplies the file and its description, message types and processing information for the receiver.','PayloadIdentifier uniquely identifies the delivered file; it is not an institution identity. No mandatory sender identifier scheme is defined by this MDR.','§2.1 p4; §2.4.1.1.1–2 p6'),
'bfh-file-receiver':('Receiving party in a file exchange',['receiving party','two business applications (receiving side)'],'The participant receiving a file and the BFH information needed to interpret its content and structure. This functional role does not determine the contained messages’ account-owner/servicer roles.','Receives processing information such as total number of message instances. The duplicate flag indicates a possible duplicate of the file; no detailed receiver decision algorithm is specified here.','No receiver identifier scheme is defined in the cited MDR.','§2.1 p4; §2.4.1.1.3 pp6–7; §2.4.1.2.3 p7'),
'bfh-service-provider':('Provider requiring application-specific file information',['service provider'],'The service-context participant whose requirements determine necessary ApplicationSpecifics business information. The source does not equate this role with the system administrator or the sending/receiving institution.','Determines necessary service-specific business information in ApplicationSpecifics. The MDR does not list an independent sequence of provider actions.','No identifier scheme for the service provider is specified.','§2.4.1.2 p7'),
'bfh-authorised-signatory':('Business entity authorised to sign a Business File',['Business Entity authorised to sign this Business File'],'The business entity authorised to sign the Business File. This file-signing role is kept distinct from the BAH-message signing role because this publication does not assert equivalence.','Its digital signature may be included in optional ApplicationSpecifics/Signature. MDR C1 permits only the XML Signature root element. The MDR does not define who grants signing authority or a signature-verification business flow.','No signatory identifier scheme is prescribed in the BFH MDR. The signature schema standard is referenced; it is not an institutional identification scheme.','§2.3 C1 p5; §2.4.1.2.2 p7')}
for rid,(title,aliases,definition,actions,ids,loc) in roles.items():
 p=PART/(rid+'.md');out=f('participant',participant_id=rid,aliases=aliases,source_ids=['src-000349'],source_edition='June 2024',source_locations=[loc],domains=['shared'],message_sets=['t2s-business-file-header'],message_ids=['head.002.001.01'],flows=['bfh-file-exchange'],limitations=['Source defines file roles and fields but no complete ordered business-process model.'])+'# '+title+'\n\n## Definition and role scope\n\n'+definition+' '+c(p,'src-000349',loc)+'\n\n## Responsibilities and actions\n\n'+actions+' '+c(p,'src-000349',loc)+'\n\n## Identifiers\n\n'+ids+' '+c(p,'src-000349',loc)+'\n\n## Relationships and applicability\n\n'+''.join('- '+l(p,PART/(x+'.md'),x)+'.\n' for x in roles if x!=rid)+'\nNo institution equivalence or automatic collapse into BAH participants is inferred.\n\n## Flow and exact message\n\n'+l(p,BFH/'flows/file-exchange.md','File-exchange reference')+' · '+l(p,MESS/'head.002.001.01/business.md','Exact BFH business reference')+'\n'
 put(p,out)
for rid in ['bfh-system-user','bfh-system-administrator']:
 p=PART/(rid+'.md');out=(ROOT/p).read_text('utf-8');out=out.replace('Source diagram comparison pending.','All supplied BFH MDR pages inspected; no substantive source diagrams.').replace('Diagram cross-checks and version applicability of MUG scenarios remain needs-review.','All BFH MDR pages and tables have visual-review evidence; the source provides no detailed ordered process for this role.').replace('flows: []','flows: ["bfh-file-exchange"]');out+='\n## Related file context\n\n'+l(p,BFH/'flows/file-exchange.md','File-exchange context, with derived ordering explicitly qualified')+'.\n';put(p,out)
# BFH flow is candidly an explanatory ordering of source-defined field responsibilities.
p=BFH/'flows/file-exchange.md';ps=list(roles)+['bfh-system-user','bfh-system-administrator'];out=f('business-flow',flow_id='bfh-file-exchange',source_ids=['src-000349'],source_edition='June 2024',source_locations=['§2.1 p4; §§2.4.1–2.4.2 pp5–8'],domains=['shared'],message_sets=['t2s-business-file-header'],message_ids=['head.002.001.01'],participants=ps,content_origin='source-grounded-explanatory-sequence',limitations=['The MDR supplies field responsibilities, not a normative ordered process or source flow diagram.'])+'# Business File exchange context\n\n## Purpose, trigger and preconditions\n\nA sender exchanges a file containing documents with a receiving party. BFH identifies the file, describes its content/type/structure, and provides processing information such as counts. The publication limits head.002 to existing implementations; its statement about future nvlp.002 is historical supplied evidence. '+c(p,'src-000349','§2.1 p4')+'\n\nThe sequence below is an explanatory ordering derived from the source-defined responsibilities and fields. The MDR does not specify a normative activity order, a trigger beyond the file exchange, or additional business preconditions.\n\n## Participants\n\n'+''.join('- '+l(p,PART/(x+'.md'),x)+'.\n' for x in ps)+'\nThe system user and system administrator occur in the field narrative even though there is no source diagram. The user is a static-data account representing an individual or application, with functions governed by granted privileges; the administrator provides no attribute distinguishing individuals from applications. '+c(p,'src-000349','§2.4.1.2.1 p7')+'\n\n## Activities and responsibilities\n\n| Explanatory step | Responsible role | Source-supported action/information | Message direction |\n| --- | --- | --- | --- |\n| 1 | File sender | Creates file; supplies unique PayloadIdentifier and CreationDateAndTime. | Local creation. |\n| 2 | File sender | Describes payload type; optional ManifestData repeats for each different item type and gives its count. | Local description. |\n| 3 (optional) | Service provider / system user context | ApplicationSpecifics carries required service business information, optional SystemUser, optional Signature and total instance count. SystemUser privileges govern available system functions. | No separate service-provider exchange specified. |\n| 4 (optional) | Authorised signatory | Includes digital signature of the business entity authorised to sign the file. | No separate signing message specified. |\n| 5 | File sender → file receiver | Exchanges file with BFH and documents; receiver obtains processing information including supplied counts. | File sender → file receiver; head.002.001.01 file context. |\n\n'+c(p,'src-000349','§2.1 p4; §§2.4.1.1–2.4.2 pp6–8')+'\n\n## Alternatives, exceptions and outcomes\n\nPayload and ManifestData may repeat zero or more times; ApplicationSpecifics is optional. If present, its total count is required by the structure. PossibleDuplicateFlag is optional and the MDR assigns omitted indicator the business default False. No duplicate-handling, cancellation, reversal, delivery acknowledgement or failure-response process is specified by this MDR. '+c(p,'src-000349','§2.2 p5; §2.4.1.1.3 p7; §§2.4.1.2–2.4.2 pp7–8')+'\n\nThe file’s identity/content/processing information is available to the receiver. The source gives no explicit postcondition asserting delivery acceptance, processing completion or equality checks between counts and payloads. Those are not manufactured as business rules.\n\n## Tables, schema and review\n\n'+l(p,FDOC/'visual-coverage.md','All 10 reviewed source tables and diagram inventory')+' · '+l(p,MESS/'head.002.001.01/structure.md','Exact XSD structure and 14 declarations')+' · '+l(p,MESS/'head.002.001.01/business.md','Purpose, rules and field usage')+'. No substantive source diagram exists in this MDR; this explanatory sequence is not labelled a source reconstruction.\n';put(p,out)
# Scoped account owner mention, insufficiently defined to merge with settlement roles.
p=PART/'bah-copy-context-account-owner.md';put(p,f('participant',participant_id='bah-copy-context-account-owner',aliases=['account owner (CopyDuplicate1Code definitions)'],source_ids=['src-000011'],source_edition='March 2024',source_locations=['§2.4.10 p15; §2.4.14.10 p24; §3.2.1.3 p51'],domains=['shared'],message_sets=['business-application-header'],message_ids=['head.001.001.04'],flows=[],limitations=['Mentioned by code definitions; ownership relationship and responsibilities are not defined in this MDR.','No equivalence to settlement AccountOwnerRole is established.'])+'# Account owner in BAH copy-code definitions\n\nThe COPY and CODU definitions describe an information copy sent to a party other than the account owner. That is the complete supplied context for this role in these definitions; the MDR does not specify the account relationship, account identifier, institution class or owner actions. '+c(p,'src-000011','§2.4.10 p15; §2.4.14.10 p24; §3.2.1.3 p51')+'\n\nThis scoped mention is not merged with the settlement AccountOwnerRole merely because the label matches. The receiving information-copy party can occupy a '+l(p,PART/'bah-receiving-messaging-endpoint.md','receiving messaging-endpoint role')+' for that message, but the source does not state that every original BAH receiver is an account owner. '+l(p,BDOC/'tables/tbl-0054.md','Complete CopyDuplicate1Code table')+'.\n')
# Exact BAH business reference.
p=MESS/'head.001.001.04/business.md';ps=['bah-sending-messaging-endpoint','bah-receiving-messaging-endpoint','bah-copy-context-account-owner'];out=f('message-business',message_id='head.001.001.04',message_family='head.001',namespace='urn:iso:std:iso:20022:tech:xsd:head.001.001.04',source_ids=['src-000011','src-000013'],source_editions=['Version 4, March 2024'],source_locations=['MDR §§2.1–2.4 pp4–25; §3 pp26–57','XSD /xs:schema'],message_sets=['business-application-header'],participants=ps,limitations=['External table validation and service/market-practice semantics are not established solely by XSD.','MUG V3 historical scenario profile is separately qualified.'])+'# head.001.001.04 — business purpose and rules\n\n## Purpose, usage and participants\n\nA new Business Message with accompanying BAH is created by its sending MessagingEndpoint for each business event/interaction in a Business Transaction. Business Message behaviour is described by the Business Transaction; structure is described by Message Definitions, Message Rules, Rules and Market Practices. Specific BAH usage may be defined by the relevant SEG. '+c(p,'src-000011','§2.1 pp4–6')+'\n\nBAH and its Business Message must not contain transport mechanics or depend on transport-message knowledge for interpretation. Business-meaningful headers/footers/envelopes remain message content. Business actors are referred to by Name in the business message, not the transport layer. From identifies the creator; To identifies the endpoint that ultimately processes it. These endpoints may differ from transport addresses. '+c(p,'src-000011','§2.1 p4; §2.4.2 p9; §2.4.3 p11')+'\n\n'+''.join('- '+l(p,PART/(x+'.md'),x)+'.\n' for x in ps)+'\n## Field usage\n\n| Building block | Source-supported meaning/condition | MDR locator |\n| --- | --- | --- |\n| CharacterSet | Character set of text-based Business Message elements; UnicodeChartsCode; table validation. | §2.4.1 p9 |\n| From / To | Sending creator / ultimate processing endpoint; person/organisation or financial-institution identification choice. | §§2.4.2–3 pp9–13 |\n| BusinessMessageIdentifier | Unambiguously identifies the Business Message to its creator. | §2.4.4 p13 |\n| MessageDefinitionIdentifier | Identifier of the Message Definition associated with this instance. | §2.4.5 p13 |\n| BusinessService | Agreed exchange rules; may identify a processing service/level. | §2.4.6 pp13–14 |\n| MarketPractice | Rules agreed to restrict usage for STP; may extend message specification with extensions/supplementary data. Registry names the registration scheme; Identification identifies the practice within it, optionally including version/date or a URN. | §2.4.7 p14 |\n| CreationDate | Date/time this Business Message header was created. | §2.4.8 p14 |\n| BusinessProcessingDate | Sender-indicated receiver processing date/time; may differ from CreationDate; usage decided by market practice or bilateral agreement. | §2.4.9 pp14–15 |\n| CopyDuplicate | COPY, DUPL or CODU per the complete source code table; Related required when this field is present. | §2.4.10 p15; C5 p8 |\n| PossibleDuplicate | If original was not received, process as original; if original was received, take action to avoid processing again. Application-level resend, not network retransmission. | §2.4.11 p15 |\n| Priority | Relative processing precedence over assigned priorities; semantics are user/service/implementation dependent. | §2.4.12 p16; §3.2.1.2 pp50–51 |\n| Signature | Digital signature of entity authorised to sign this Business Message; W3C XML Signature context and OnlySignatureElement constraint. | §2.4.13 p16; C4 p8 |\n| Related | Headers of messages to which this message relates; may be used for query replies, cancellation or amendment. | §2.4.14 pp16–25 |\n\nAll rows: '+c(p,'src-000011','§2.4 pp9–25')+' Copy or duplicate flags themselves do not define a settlement cancellation or movement reversal. Related can point to such contextual messages but does not prescribe their message family.\n\nRelated/CreationDate requires times normalized with the Z annotation (MDR §2.4.14.8 p23); the top-level definition on p14 does not repeat this note. Preserve this as a related-header usage condition, not an XSD facet.\n\n## All source-defined constraints\n\n| ID | Constraint | Source meaning |\n| --- | --- | --- |\n| C1 | AnyBIC | Valid ISO 9362 registered Business identifier code for financial or non-financial institution; 8 or 11 contiguous characters. |\n| C2 | BICFI | Valid registered financial-institution BIC; 8 or 11 contiguous characters. |\n| C3 | Country | Check against United Nations country names / ISO 3166 Alpha-2 list. |\n| C4 | OnlySignatureElement | Of the possible XML Signature namespace global roots, only Signature is permitted. |\n| C5 | RelatedPresentWhenCopyDupl | Related contains relevant BusinessMessageHeader elements; when CopyDuplicate is present, Related[1] must be present. MessageDefinition-level rule. |\n| C6 | ValidationByTable | Applies to CharacterSet; UnicodeChartsCode names Unicode blocks. No actual block enumeration is supplied in this MDR. |\n| C7 | ValidationByTable | Applies to Priority; the relevant user community defines the meaning of its priority values. No universal priority enumeration is supplied here. |\n\n'+c(p,'src-000011','§2.3 pp8–9; §3.2.1.2 pp50–51; §3.2.1.11 p53')+'\n\nThese source business/table-validation requirements remain separate from XSD syntax. For example, a matching BIC pattern does not establish registry validity, and the XSD does not replace contextual priority semantics or C5 business validation.\n\n## Structures, tables and related context\n\n'+l(p,MESS/'head.001.001.04/structure.md','Complete exact XSD structure and 55 declarations')+' contains all structural cardinalities, types and schema restrictions. '+l(p,BDOC/'visual-coverage.md','All 76 reviewed MDR tables, including 19 unruled facet blocks')+' preserves source hierarchy and complete code definitions. The MDR contains no substantive source diagram.\n\nThe MDR p7 labels its structure “Message root <Document> <AppHdr>”; the supplied XSD declares AppHdr at /xs:schema/xs:element. That generic table wording is preserved and is not used to introduce an extra Document wrapper. '+c(p,'src-000013','targetNamespace; /xs:schema/xs:element[@name="AppHdr"]')+'\n\n'+l(p,SETS/'business-application-header/2021-11-03-v3.0/flows/index.md','Historical MUG usage scenarios and source diagrams')+' are guide-level context. Its packaging example uses V03; it is not silently an exact V04 implementation profile. '+l(p,Path('shared/reference/concepts/business-application-header-and-business-file-header.md'),'BAH versus BFH')+'.\n';put(p,out)
# Exact BFH business reference.
p=MESS/'head.002.001.01/business.md';ps=list(roles)+['bfh-system-user','bfh-system-administrator'];out=f('message-business',message_id='head.002.001.01',message_family='head.002',namespace='urn:iso:std:iso:20022:tech:xsd:head.002.001.01',source_ids=['src-000349','src-000261'],source_editions=['June 2024'],source_locations=['MDR §§2.1–2.4 pp4–8; §3 pp9–10','XSD /xs:schema'],message_sets=['t2s-business-file-header'],participants=ps,flows=['bfh-file-exchange'],limitations=['The supplied MDR does not define a complete ordered business process or a source business-flow diagram.','Historical nvlp.002 statement does not establish current external availability.'])+'# head.002.001.01 — file exchange purpose and rules\n\n## Purpose and usage boundary\n\nThe BFH supplies information about file-exchange parties, content and structure. It identifies the sender, uniquely identifies the exchanged file, describes the message types (ISO 20022 definitions by default), and supplies receiver processing information such as message-instance counts. Its two building blocks are PayloadDescription and Payload. '+c(p,'src-000349','§2.1 p4')+'\n\nThe supplied June2024 publication limits head.002 to existing implementations such as the Eurosystem, says it will not be maintained, and directs new implementations toward its then-upcoming Business File Envelope nvlp.002. This is a statement of that publication; no supplied nvlp.002 schema or current product status is established. Missing nvlp.002 is not an XSD import failure. '+c(p,'src-000349','§§1.1–2.1 pp3–4')+'\n\n## Participants\n\n'+''.join('- '+l(p,PART/(x+'.md'),x)+'.\n' for x in ps)+'\nRoles are contextual. A system user represents an individual or application; its granted privileges determine available functions. The source does not distinguish those categories through an administrator attribute. '+c(p,'src-000349','§2.4.1.2.1 p7')+'\n\n## Fields and source rules\n\n| Field/context | Definition, condition or business rule | MDR locator |\n| --- | --- | --- |\n| PayloadDescription / PayloadData | Describes payload and identifies the exchanged instance. | §§2.4.1–2.4.1.1 pp5–6 |\n| PayloadIdentifier | Unique file identifier assigned by sender. | §2.4.1.1.1 p6 |\n| CreationDateAndTime | Date/time file was created by sender. | §2.4.1.1.2 p6 |\n| PossibleDuplicateFlag | Possible duplicate of file between two business applications; if omitted, source business meaning is False. | §2.4.1.1.3 pp6–7 |\n| ApplicationSpecifics | Optional block of business information necessary to the service provider. | §2.4.1.2 p7 |\n| SystemUser | Optional static-data user account, representing individual or application and privileges. | §2.4.1.2.1 p7 |\n| Signature | Optional digital signature of business entity authorised to sign the Business File. | §2.4.1.2.2 p7 |\n| TotalNumberOfDocuments | Total message-instance count within the file; mandatory within present ApplicationSpecifics. | §2.2 p5; §2.4.1.2.3 p7 |\n| PayloadType | Identifies type of payload. | §2.4.1.3 p8 |\n| ManifestData | Repeats for each different item type, describing related items/attachments. | §2.4.1.4 p8 |\n| DocumentType / NumberOfDocuments | Declared item type and instance count for that type; catalogue area examples include admi, camt, pacs, sese and semt. | §§2.4.1.4.1–2 p8 |\n| Payload | Contains exchanged documents; permits any XML namespace with lax processing. Validate against an available uniquely determined declaration; otherwise absence of validation is permitted. | §2.4.2 p8 |\n\nAll source rows: '+c(p,'src-000349','§2.4 pp5–8')+' No reconciliation equation for total count versus manifest/payload counts is stated here; no additional rule is invented.\n\nC1 OnlySignatureElement permits only the Signature root from XML Signature namespace. The source references XML Signature Syntax and Processing Second Edition (10 June2008). Keep this source business rule distinct from the XSD’s lax namespace wildcard. '+c(p,'src-000349','§2.3 p5; §2.4.1.2.2 p7')+'\n\nThe omitted PossibleDuplicateFlag has source-defined meaning False, while its optional XSD element declares no default attribute. The distinction matters for schema-only validators. '+c(p,'src-000261','/xs:schema/xs:complexType[@name="PayloadData2"]/xs:sequence/xs:element[@name="PssblDplctFlg"]')+'\n\n## Datatypes, full structure and evidence\n\n'+l(p,MESS/'head.002.001.01/structure.md','Complete exact XSD structure and 14 declarations')+' supplies all ordering, cardinalities, wildcards and restrictions. '+l(p,FDOC/'visual-coverage.md','All 10 reviewed MDR tables, including four unruled format blocks')+' includes Number(totalDigits18,fractionDigits0), Max140Text, Max256Text and Max35Text facets. ISODateTime permits date/time with UTC, offset or local representations; parties agree any fractional-second digit limit. '+c(p,'src-000349','§3.1 pp9–10')+'\n\nThe MDR p5 prints “Message root <Document> <Xchg>”; the supplied schema declares Xchg at /xs:schema/xs:element. The table wording is retained without inventing an extra Document wrapper. '+c(p,'src-000261','targetNamespace; /xs:schema/xs:element[@name="Xchg"]')+'\n\n'+l(p,BFH/'flows/file-exchange.md','File-exchange responsibilities and source limitations')+' is an explicitly explanatory ordering of field semantics. All10 source pages were rendered and inspected; no substantive source diagram exists. '+l(p,Path('shared/reference/concepts/business-application-header-and-business-file-header.md'),'BAH versus BFH scope')+'.\n';put(p,out)
